const url = window.location.href;
if (navigator.share) {
  navigator.share({ title: (partner.data && partner.data.partner_name) || 'Partner', url }).catch(() => {});
} else {
  navigator.clipboard.writeText(url).then(() => {
    toast({ title: 'Link copied', text: 'Profile link copied to clipboard', icon: 'check' });
  });
}

if (!myContext.data || !myContext.data.customer) {
  window.location.href = '/login?redirect-to=' + encodeURIComponent(window.location.pathname);
  return;
}
const partnerName = route.params.partner_id;
const previous = myShortlist.data || [];
const wasShortlisted = previous.includes(partnerName);
myShortlist.data = wasShortlisted ? previous.filter((n) => n !== partnerName) : [...previous, partnerName];
const fn = wasShortlisted ? 'connect.api.customer.remove_from_shortlist' : 'connect.api.customer.add_to_shortlist';
call(fn, { partner: partnerName }).then(() => { myShortlist.reload(); }).catch((err) => {
  myShortlist.data = previous;
  toast({ title: 'Could not update shortlist', text: (err && err.message) || 'Please try again', icon: 'x' });
});

if (!myContext.data || !myContext.data.customer) {
  window.location.href = '/login?redirect-to=' + encodeURIComponent(window.location.pathname);
  return;
}
call('connect.api.contact.start_partner_thread', { partner: route.params.partner_id }).then((result) => {
  const query = { thread: result && result.thread };
  if (result && result.is_new_thread) query.requirement = '1';
  router.push('/messaging-d87b?' + new URLSearchParams(query).toString());
}).catch((err) => {
  toast({ title: 'Could not start conversation', text: (err && err.message) || 'Please try again', icon: 'x' });
});

